import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideHttpClient, withFetch } from '@angular/common/http';
import { provideRouter } from '@angular/router';
import { routes } from './app.routes';

export const appConfig: ApplicationConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideRouter(routes),
    provideHttpClient(withFetch()),
  ],
};

import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';

export interface Product {
  id: number;
  name: string;
  price: number;
}

@Injectable({ providedIn: 'root' })
export class ProductsApi {
  private readonly http = inject(HttpClient);

  list(): Observable<Product[]> {
    return this.http.get<Product[]>('/api/products');
  }

  create(product: Omit<Product, 'id'>): Observable<Product> {
    return this.http.post<Product>('/api/products', product);
  }
}

import { Component, inject } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { Product, ProductsApi } from '../products-api';

@Component({
  selector: 'app-product-list',
  template: `
    <ul>
      @for (product of products(); track product.id) {
        <li>{{ product.name }} - {{ product.price }} EUR</li>
      } @empty {
        <li>No products yet.</li>
      }
    </ul>
  `,
})
export class ProductList {
  private readonly api = inject(ProductsApi);
  readonly products = toSignal(this.api.list(), { initialValue: [] as Product[] });
}

import { Component, signal } from '@angular/core';
import { httpResource } from '@angular/common/http';
import { Product } from '../products-api';

@Component({
  selector: 'app-catalog',
  template: `
    <select #cat (change)="category.set(cat.value)">
      <option value="all">All</option>
      <option value="audio">Audio</option>
    </select>
    <button (click)="products.reload()">Refresh</button>

    @if (products.isLoading()) {
      <p>Loading...</p>
    } @else if (products.error()) {
      <p>Could not load products.</p>
    } @else {
      <ul>
        @for (product of products.value(); track product.id) {
          <li>{{ product.name }}</li>
        } @empty {
          <li>No products in this category.</li>
        }
      </ul>
    }
  `,
})
export class Catalog {
  readonly category = signal('all');

  readonly products = httpResource<Product[]>(
    () => ({
      url: '/api/products',
      params: { category: this.category() },
    }),
    { defaultValue: [] },
  );
}

import { resource, signal } from '@angular/core';

const userId = signal(7);

const user = resource({
  params: () => ({ id: userId() }),
  loader: async ({ params, abortSignal }) => {
    const response = await fetch(`/api/users/${params.id}`, { signal: abortSignal });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    return (await response.json()) as { id: number; name: string };
  },
});

import { HttpInterceptorFn } from '@angular/common/http';
import { inject } from '@angular/core';
import { AuthService } from './auth-service';

export const authInterceptor: HttpInterceptorFn = (req, next) => {
  const token = inject(AuthService).token();
  if (!token) {
    return next(req);
  }
  return next(req.clone({ setHeaders: { Authorization: `Bearer ${token}` } }));
};

